// Voter proof-of-possession, `seam-voter-pop-v1` (seam-runtime #1687, runtime 0.87.0).
//
// `conformance/voter_pop_v1_payload_vector.json` is a byte-identical copy of the runtime's fixture,
// generated by an implementation independent of the Rust one. The content digest, the frozen entry
// bytes, the signed payload AND the deterministic Ed25519 signature are compared to its bytes. No bless
// mode. Twin of python/tests/test_voter_pop.py.

import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { test } from "node:test";

import { create } from "@bufbuild/protobuf";
import type { DescMessage, DescMethodUnary, MessageInitShape } from "@bufbuild/protobuf";
import type { Transport, UnaryResponse } from "@connectrpc/connect";

import { Agent, SeamClient, type VoterProofInput } from "../src/client.js";
import {
  VOTER_POP_V1_DOMAIN,
  VOTE_CONTENT_V1_DOMAIN,
  signVoterPop,
  verifyVoterPop,
  voteContentDigest,
  voteEntryBytes,
  voterPopPayload,
  voterPopToRest,
  type VoteEntryInput,
  type VoterPopTarget,
  type VoterPopProof,
} from "../src/crypto.js";
import { BallotChoice, VoterPopSchema, VoterProofSchema } from "../gen/seam/api/v1/seam_pb.js";

type Case = {
  name: string;
  seed_hex: string;
  voter_aid: string;
  target: { issuer: string; audience: string; tenant: string; namespace: string; session_id: string; opened_at_millis: number };
  content: {
    mode: string;
    proposal_id: string;
    content: string;
    participants: string[];
    on_behalf_of: string[];
    context: { ctx_ref: string; content_hash: string }[] | [string, string][];
    features: [string, string][];
    policy: { policy_version: string; rules_digest_hex: string } | null;
  };
  content_digest_hex: string;
  entry: { kind: string; participant: string; proposal_id: string; value: string; reason: string; confidence: number | null; rationale_ref: string | null };
  entry_bytes_hex: string;
  issued_at_ms: number;
  expires_at_ms: number;
  payload_hex: string;
  signature_hex: string;
};

const here = dirname(fileURLToPath(import.meta.url));
const VECTOR = JSON.parse(readFileSync(join(here, "..", "..", "conformance", "voter_pop_v1_payload_vector.json"), "utf8")) as {
  domain: string;
  content_domain: string;
  cases: Case[];
};
const CASES = VECTOR.cases;

const hex = (b: Uint8Array) => Buffer.from(b).toString("hex");
const unhex = (h: string) => new Uint8Array(Buffer.from(h, "hex"));

function target(c: Case): VoterPopTarget {
  const t = c.target;
  return { issuer: t.issuer, audience: t.audience, tenant: t.tenant, namespace: t.namespace, sessionId: t.session_id, openedAtMillis: t.opened_at_millis };
}
function content(c: Case): Uint8Array {
  const k = c.content;
  const ctx = (k.context as unknown[]).map((x) =>
    Array.isArray(x) ? ([x[0], x[1]] as [string, string]) : { ctxRef: (x as { ctx_ref: string }).ctx_ref, contentHash: (x as { content_hash: string }).content_hash },
  );
  const policy = k.policy ? { policyVersion: k.policy.policy_version, rulesDigest: unhex(k.policy.rules_digest_hex) } : null;
  return voteContentDigest(k.mode, k.proposal_id, k.content, k.participants, k.on_behalf_of, ctx, {
    features: k.features.map((f) => [f[0], f[1]] as const),
    policy,
  });
}
function entry(c: Case): VoteEntryInput {
  const e = c.entry;
  return { kind: e.kind, participant: e.participant, proposalId: e.proposal_id, value: e.value, reason: e.reason, confidence: e.confidence, rationaleRef: e.rationale_ref };
}

test("the vector is populated and the domains match", () => {
  assert.ok(CASES.length >= 11);
  assert.equal(VOTER_POP_V1_DOMAIN, VECTOR.domain);
  assert.equal(VOTE_CONTENT_V1_DOMAIN, VECTOR.content_domain);
});

for (const c of CASES) {
  test(`every byte matches the vector: ${c.name}`, () => {
    const digest = content(c);
    assert.equal(hex(digest), c.content_digest_hex);
    const eb = voteEntryBytes(entry(c));
    assert.equal(hex(eb), c.entry_bytes_hex);
    assert.equal(hex(voterPopPayload(target(c), c.voter_aid, digest, c.issued_at_ms, c.expires_at_ms, eb)), c.payload_hex);
    const pop = signVoterPop(unhex(c.seed_hex), target(c), digest, entry(c), { issuedAtMs: c.issued_at_ms, expiresAtMs: c.expires_at_ms });
    assert.equal(pop.voterAid, c.voter_aid);
    assert.equal(hex(pop.signature), c.signature_hex);
    assert.ok(verifyVoterPop(target(c), pop.voterAid, digest, pop.issuedAtMs, pop.expiresAtMs, eb, pop.signature));
  });
}

test("the other-* cases differ from basic", () => {
  const by = Object.fromEntries(CASES.map((c) => [c.name, c]));
  for (const n of ["other-session", "other-opened-at", "other-audience", "other-content", "other-key", "other-features", "no-features", "other-policy-rules", "other-policy-id", "no-policy"])
    assert.notEqual(by[n]!.signature_hex, by["basic"]!.signature_hex, n);
});

test("a signature does not verify for another target", () => {
  const c = CASES[0]!;
  const pop = signVoterPop(unhex(c.seed_hex), target(c), content(c), entry(c), { issuedAtMs: c.issued_at_ms, expiresAtMs: c.expires_at_ms });
  const other = { ...target(c), sessionId: "s-other" };
  assert.equal(verifyVoterPop(other, pop.voterAid, content(c), pop.issuedAtMs, pop.expiresAtMs, entry(c), pop.signature), false);
});

test("-0 confidence folds to +0", () => {
  const e = { kind: "vote", participant: "a", proposalId: "p", value: "APPROVE" };
  assert.deepEqual(voteEntryBytes({ ...e, confidence: -0 }), voteEntryBytes({ ...e, confidence: 0 }));
  assert.notDeepEqual(voteEntryBytes({ ...e, confidence: 0 }), voteEntryBytes(e));
});

for (const [issued, expires] of [[10, 9], [0, 15 * 60 * 1000 + 1]] as const) {
  test(`a window the runtime must refuse is never signed: [${issued}, ${expires}]`, () => {
    const c = CASES[0]!;
    assert.throws(() => signVoterPop(unhex(c.seed_hex), target(c), content(c), entry(c), { issuedAtMs: issued, expiresAtMs: expires }), /window/);
  });
}

test("the default window is now + 5 minutes", () => {
  const c = CASES[0]!;
  const pop = signVoterPop(unhex(c.seed_hex), target(c), content(c), entry(c));
  assert.equal(pop.expiresAtMs - pop.issuedAtMs, 300_000n);
});

test("REST form: unpadded base64url signature, numeric window", () => {
  const pop: VoterPopProof = { voterAid: "aid:pubkey:ed25519:x", issuedAtMs: 1n, expiresAtMs: 2n, signature: new Uint8Array(64).fill(1) };
  const r = voterPopToRest(pop);
  assert.equal(r.pop.issued_at_ms, 1);
  assert.ok(!r.pop.signature.includes("="));
});

// ── wiring: the proof reaches the wire ────────────────────────────────────────────────────────────

interface Recorded {
  method: string;
  input: Record<string, unknown>;
}
function fakeTransport(calls: Recorded[]): Transport {
  return {
    async unary<I extends DescMessage, O extends DescMessage>(
      method: DescMethodUnary<I, O>,
      _signal: AbortSignal | undefined,
      _timeoutMs: number | undefined,
      _header: HeadersInit | undefined,
      input: MessageInitShape<I>,
    ): Promise<UnaryResponse<I, O>> {
      calls.push({ method: method.name, input: input as Record<string, unknown> });
      let out: Record<string, unknown> = {};
      if (method.name === "Admit") out = { ticket: new Uint8Array([1]), expiresAtMs: 9_999_999_999_999n };
      return { stream: false, service: method.parent, method, header: new Headers(), trailer: new Headers(), message: create(method.output, out as MessageInitShape<O>) };
    },
    stream() {
      throw new Error("not used in this suite");
    },
  };
}

const POP: VoterPopProof = { voterAid: "aid:pubkey:ed25519:v", issuedAtMs: 1n, expiresAtMs: 2n, signature: new Uint8Array(64).fill(7) };
const POP_PB = create(VoterProofSchema, { proof: { case: "pop", value: create(VoterPopSchema, { ...POP }) } });

function wireSig(input: Record<string, unknown>): Uint8Array | undefined {
  const p = input["proof"] as { proof?: { case: string; value: { signature: Uint8Array } } } | undefined;
  return p?.proof?.value.signature;
}

test("submitVote / submitObjection / submitBallot carry the proof; omitted ⇒ none sent", async () => {
  const calls: Recorded[] = [];
  const client = new SeamClient(fakeTransport(calls));
  await client.submitVote("s", "risk", "p1", "APPROVE", undefined, { proof: POP });
  await client.submitObjection("s", "risk", "p1", "why", { proof: POP_PB });
  await client.submitBallot("s", "risk", "ar-1", BallotChoice.APPROVE, "", undefined, { proof: POP });
  for (const m of ["SubmitVote", "SubmitObjection", "SubmitBallot"]) {
    const c = calls.find((x) => x.method === m)!;
    assert.deepEqual(wireSig(c.input), POP.signature, m);
  }
  calls.length = 0;
  await client.submitVote("s", "risk", "p1", "APPROVE");
  assert.equal(calls.find((x) => x.method === "SubmitVote")!.input["proof"], undefined);
});

for (const [name, bad] of [
  ["a string", "sig"],
  ["an empty object", { pop: {} }],
  ["a 63-byte signature", { ...POP, signature: new Uint8Array(63) }],
] as const) {
  test(`a malformed proof (${name}) is refused before the wire`, async () => {
    const calls: Recorded[] = [];
    const client = new SeamClient(fakeTransport(calls));
    await assert.rejects(client.submitVote("s", "risk", "p1", "APPROVE", undefined, { proof: bad as unknown as VoterProofInput }));
    assert.equal(calls.length, 0);
  });
}

test("runDecision votes carry their proofs", async () => {
  const calls: Recorded[] = [];
  const client = new SeamClient(fakeTransport(calls));
  await client.runDecision(new Agent(new Uint8Array(32).fill(42)), "sid-0123456789abcdefghijkl", ["risk", "fraud", "x"], [
    ["risk", "APPROVE", "", POP],
    ["fraud", "REJECT", "too risky"],
    ["x", "ABSTAIN", "", POP_PB],
  ]);
  const votes = calls.find((c) => c.method === "RunDecision")!.input["votes"] as Record<string, unknown>[];
  assert.deepEqual(wireSig(votes[0]!), POP.signature);
  assert.equal(votes[0]!["reason"], "");
  assert.equal(votes[1]!["proof"], undefined);
  assert.deepEqual(wireSig(votes[2]!), POP.signature);
  await assert.rejects(
    client.runDecision(new Agent(new Uint8Array(32).fill(42)), "sid-0123456789abcdefghijkl", ["a"], [
      ["a", "b", "c", POP, "extra"] as unknown as readonly [string, string],
    ]),
    TypeError,
  );
});

// ── the sealed record re-check (verifyVoterRecord / verifyCommitmentVoters) ────────────────────────

import { verifyCommitmentVoters, verifyVoterRecord, type ExplanationEntryInput } from "../src/crypto.js";

const TCT = JSON.parse(readFileSync(join(here, "..", "..", "conformance", "vectors.json"), "utf8")).tct as {
  issuer_aid: string;
  inputs: { commitment: { explanation: ExplanationEntryInput[] } };
};
// The vector carries a record's bytes as `*_hex` keys; the record input takes them as `DigestBytes`.
const ENTRIES: ExplanationEntryInput[] = TCT.inputs.commitment.explanation.map((e) => {
  const raw = e.voter_verification as unknown as Record<string, unknown> | null | undefined;
  if (!raw) return e;
  return {
    ...e,
    voter_verification: {
      ...(raw as object),
      content_digest: raw["content_digest_hex"] as string,
      signature: raw["signature_hex"] as string,
      signer_certificate: raw["signer_certificate_hex"] as string,
    } as NonNullable<ExplanationEntryInput["voter_verification"]>,
  };
});
const VOTE = ENTRIES.find((e) => e.kind === "vote")!;

test("the conformance vote's sealed record re-verifies, and the commitment check passes", () => {
  assert.ok(VOTE.voter_verification);
  assert.equal(verifyVoterRecord(VOTE), true);
  assert.equal(verifyCommitmentVoters(ENTRIES, TCT.issuer_aid), true);
  const vv = VOTE.voter_verification!;
  assert.equal(verifyCommitmentVoters(ENTRIES, TCT.issuer_aid, [vv.tenant, vv.session_id]), true);
});

test("the commitment-level voter check fails closed", () => {
  const vv = VOTE.voter_verification!;
  const swap = (e: Partial<ExplanationEntryInput>) => ENTRIES.map((x) => (x === VOTE ? { ...x, ...e } : x));
  const cases: [string, ExplanationEntryInput[], string, (readonly [string, string])?][] = [
    ["another pinned issuer", ENTRIES, "aid:pubkey:ed25519:" + "A".repeat(43)],
    ["another decision's session", ENTRIES, TCT.issuer_aid, [vv.tenant, "s-other"]],
    ["a vote without its record", swap({ voter_verification: null }), TCT.issuer_aid],
    ["a tampered reason", swap({ reason: VOTE.reason + "!" }), TCT.issuer_aid],
    ["an evaluation with a record", ENTRIES.map((x) => (x.kind === "evaluation" ? { ...x, voter_verification: vv } : x)), TCT.issuer_aid],
    ["a record outside its window", swap({ voter_verification: { ...vv, accepted_at_ms: BigInt(vv.expires_at_ms) + 1n } }), TCT.issuer_aid],
    ["a non-pop method", swap({ voter_verification: { ...vv, method: "cp_signed" } }), TCT.issuer_aid],
  ];
  for (const [name, entries, issuer, decision] of cases)
    assert.equal(verifyCommitmentVoters(entries, issuer, decision), false, name);
});

test("features frame sorted, a repeated key is refused, and the policy slot needs 32 bytes", () => {
  const by = Object.fromEntries(VECTOR.cases.map((c) => [c.name, c]));
  assert.equal(by["features-order-a"]!.content_digest_hex, by["features-order-b"]!.content_digest_hex);
  const base = ["macp.mode.decision.v1", "p1", "APPROVE", ["a"], [], []] as const;
  assert.deepEqual(
    voteContentDigest(...base, { features: { b: "1", a: "2" } }),
    voteContentDigest(...base, { features: [["a", "2"], ["b", "1"]] }),
  );
  assert.throws(() => voteContentDigest(...base, { features: [["a", "1"], ["a", "1"]] }), /twice/);
  assert.throws(() => voteContentDigest(...base, { policy: { policyVersion: "p", rulesDigest: new Uint8Array(31) } }), /32 bytes/);
  assert.notDeepEqual(voteContentDigest(...base, { policy: { policyVersion: "p", rulesDigest: new Uint8Array(32) } }), voteContentDigest(...base));
});
